<?php
namespace App\Http\Controllers\Api;
use App\Http\Controllers\Controller; use App\Models\{Patient,Observation,Assessment,CarePlan,Referral,MedicalReport,Notification,Consultation}; use Illuminate\Http\Request; use Illuminate\Support\Facades\Http; use Illuminate\Support\Facades\Storage;
class ClinicalController extends Controller {
 public function dashboard(Request $r){$role=$r->user()->role;$patientIds=Patient::query();if($role==='patient')$patientIds->where('user_id',$r->user()->id);elseif($role==='caregiver')$patientIds->whereIn('id',\App\Models\CaregiverAccess::where('caregiver_id',$r->user()->id)->where('status','approved')->pluck('patient_id'));$visibleIds=$patientIds->pluck('id');$patients=in_array($role,['doctor','admin','specialist'])?Patient::count():$visibleIds->count();$obs=Observation::whereDate('created_at',today())->when(!in_array($role,['doctor','admin','specialist']),fn($q)=>$q->whereIn('patient_id',$visibleIds))->count();$pending=Assessment::where('doctor_status','pending')->when($role==='patient',fn($q)=>$q->whereIn('patient_id',$visibleIds))->when($role==='caregiver',fn($q)=>$q->whereIn('patient_id',$visibleIds))->count();$alerts=Observation::where(function($q){$q->where('spo2','<',94)->orWhere('temperature','>=',39)->orWhere('heart_rate','>=',120);})->when(!in_array($role,['doctor','admin','specialist']),fn($q)=>$q->whereIn('patient_id',$visibleIds))->count();$recent=Assessment::with('patient.user')->when($role==='patient'||$role==='caregiver',fn($q)=>$q->whereIn('patient_id',$visibleIds))->latest()->limit(6)->get();return response()->json(['role'=>$role,'patients'=>$patients,'observations_today'=>$obs,'pending_reviews'=>$pending,'rule_flags'=>$alerts,'recent_assessments'=>$recent]);}
 public function predict(Request $r){$d=$r->validate(['patient_id'=>'required|exists:patients,id','symptoms'=>'required|array|min:1','symptoms.*'=>'string|max:80']);$p=Patient::findOrFail($d['patient_id']);abort_unless($r->user()->role==='admin'||$r->user()->id===$p->user_id||in_array($r->user()->role,['doctor','specialist'])||($r->user()->role==='caregiver'&&\App\Models\CaregiverAccess::where('patient_id',$p->id)->where('caregiver_id',$r->user()->id)->where('status','approved')->exists()),403);$url=rtrim(env('ML_SERVICE_URL','http://127.0.0.1:5001'),'/').'/predict';try{$res=Http::timeout(15)->post($url,['symptoms'=>$d['symptoms']]);if(!$res->successful())return response()->json(['message'=>'ML service error','detail'=>$res->json()],502);$out=$res->json();}catch(\Throwable $e){return response()->json(['message'=>'ML service unavailable'],503);} $a=Assessment::create(['patient_id'=>$p->id,'created_by'=>$r->user()->id,'symptoms'=>$d['symptoms'],'predicted_label'=>$out['prediction'],'department'=>$out['suggested_department']??'General Medicine','priority'=>'review','explanation'=>'Model-generated preliminary suggestion. Requires clinician review.','doctor_status'=>'pending']);return response()->json(['assessment'=>$a,'notice'=>'Educational decision support only; not a diagnosis.'],201);}
 public function observations(Request $r,Patient $patient){abort_unless($r->user()->role==='admin'||$r->user()->id===$patient->user_id||in_array($r->user()->role,['doctor','specialist'])||($r->user()->role==='caregiver'&&\App\Models\CaregiverAccess::where('patient_id',$patient->id)->where('caregiver_id',$r->user()->id)->where('status','approved')->exists()),403);return $patient->observations()->latest('recorded_at')->get();}
 public function addObservation(Request $r,Patient $patient){abort_unless($r->user()->role==='admin'||$r->user()->id===$patient->user_id||in_array($r->user()->role,['doctor','specialist'])||($r->user()->role==='caregiver'&&\App\Models\CaregiverAccess::where('patient_id',$patient->id)->where('caregiver_id',$r->user()->id)->where('status','approved')->exists()),403);$d=$r->validate(['temperature'=>'nullable|numeric|between:30,45','spo2'=>'nullable|integer|between:50,100','heart_rate'=>'nullable|integer|between:20,250','systolic_bp'=>'nullable|integer|between:50,260','diastolic_bp'=>'nullable|integer|between:30,160','symptoms'=>'nullable|array','notes'=>'nullable|string|max:2000','recorded_at'=>'nullable|date']);$previous=$patient->observations()->latest('recorded_at')->limit(3)->get();$o=$patient->observations()->create($d+['recorded_by'=>$r->user()->id]);$flags=[];if(($d['spo2']??101)<94)$flags[]='SpO2 reading is below the configured review threshold';if(($d['temperature']??0)>=39)$flags[]='High temperature reading entered';if(($d['heart_rate']??0)>=120)$flags[]='High heart-rate reading entered';$priorSpo2=$previous->pluck('spo2')->filter()->values();if(isset($d['spo2'])&&$priorSpo2->count()>=2&&$d['spo2']<$priorSpo2->first()&&$priorSpo2->first()<$priorSpo2->last())$flags[]='Recent SpO2 readings show a downward pattern; clinician review reminder';$priorTemp=$previous->pluck('temperature')->filter()->values();if(isset($d['temperature'])&&$priorTemp->count()>=2&&$d['temperature']>$priorTemp->first()&&$priorTemp->first()>=$priorTemp->last())$flags[]='Recent temperature readings show an upward pattern; clinician review reminder';if($flags){$doctors=\App\Models\User::whereIn('role',['doctor','admin'])->get();foreach($doctors as $u)Notification::create(['user_id'=>$u->id,'title'=>'Observation needs review','body'=>'Patient #'.$patient->id.': '.implode('; ',$flags)]);}return response()->json(['observation'=>$o,'review_flags'=>$flags,'notice'=>'Flags are configured reminders, not a clinical risk score.'],201);}
 public function assessments(Request $r){if($r->user()->role==='caregiver')return response()->json(['data'=>[],'total'=>0]);$q=Assessment::with('patient.user')->latest();if($r->user()->role==='patient')$q->whereHas('patient',fn($x)=>$x->where('user_id',$r->user()->id));return $q->paginate(20);}
 public function reviewAssessment(Request $r,Assessment $assessment){abort_unless(in_array($r->user()->role,['doctor','specialist','admin']),403);$d=$r->validate(['doctor_status'=>'required|in:accepted,rejected,needs_followup','doctor_note'=>'nullable|string|max:2000']);$assessment->update($d);return $assessment;}
 public function carePlans(Request $r,Patient $patient){abort_unless($r->user()->role==='admin'||$r->user()->id===$patient->user_id||in_array($r->user()->role,['doctor','specialist'])||($r->user()->role==='caregiver'&&\App\Models\CaregiverAccess::where('patient_id',$patient->id)->where('caregiver_id',$r->user()->id)->where('status','approved')->exists()),403);return $patient->carePlans()->latest()->get();}
 public function addCarePlan(Request $r,Patient $patient){abort_unless(in_array($r->user()->role,['doctor','admin']),403);$d=$r->validate(['title'=>'required|string|max:160','instructions'=>'required|string|max:5000','reminder_at'=>'nullable|date']);return response()->json($patient->carePlans()->create($d+['doctor_id'=>$r->user()->id,'status'=>'active']),201);}
 public function referrals(Request $r){if($r->user()->role==='caregiver')return response()->json([]);$q=Referral::with('patient.user')->latest();if($r->user()->role==='specialist')$q->where('specialist_id',$r->user()->id);if($r->user()->role==='patient')$q->whereHas('patient',fn($x)=>$x->where('user_id',$r->user()->id));return $q->get();}
 public function addReferral(Request $r,Patient $patient){abort_unless(in_array($r->user()->role,['doctor','admin']),403);$d=$r->validate(['specialist_id'=>'required|exists:users,id','department'=>'required|string','reason'=>'required|string|max:2000']);return response()->json(Referral::create($d+['patient_id'=>$patient->id,'doctor_id'=>$r->user()->id,'status'=>'pending']),201);}
 public function referralNote(Request $r,Referral $referral){abort_unless(in_array($r->user()->role,['specialist','admin']),403);$d=$r->validate(['specialist_note'=>'required|string|max:3000','status'=>'required|in:reviewed,completed']);$referral->update($d);return $referral;}
 public function uploadReport(Request $r,Patient $patient){abort_unless($r->user()->role==='admin'||$r->user()->id===$patient->user_id||in_array($r->user()->role,['doctor','specialist'])||($r->user()->role==='caregiver'&&\App\Models\CaregiverAccess::where('patient_id',$patient->id)->where('caregiver_id',$r->user()->id)->where('status','approved')->exists()),403);$d=$r->validate(['report'=>'required|file|mimes:pdf,jpg,jpeg,png|max:5120','description'=>'nullable|string|max:500']);$f=$d['report'];$path=$f->store('reports','public');return response()->json(MedicalReport::create(['patient_id'=>$patient->id,'uploaded_by'=>$r->user()->id,'original_name'=>$f->getClientOriginalName(),'file_path'=>$path,'mime_type'=>$f->getMimeType(),'file_size'=>$f->getSize(),'description'=>$d['description']??null]),201);}
 public function notifications(Request $r){return Notification::where('user_id',$r->user()->id)->latest()->limit(50)->get();}
 public function readNotification(Request $r,Notification $notification){abort_unless($notification->user_id===$r->user()->id,403);$notification->update(['read_at'=>now()]);return $notification;}
 public function consultations(Request $r){if($r->user()->role==='caregiver')return response()->json([]);$q=Consultation::latest();if($r->user()->role==='patient')$q->whereHas('patient',fn($x)=>$x->where('user_id',$r->user()->id));return $q->get();}
 public function addConsultation(Request $r,Patient $patient){abort_unless(in_array($r->user()->role,['doctor','admin']),403);$d=$r->validate(['scheduled_at'=>'required|date|after:now','meeting_url'=>'nullable|url|max:500']);return response()->json(Consultation::create($d+['patient_id'=>$patient->id,'doctor_id'=>$r->user()->id,'status'=>'scheduled']),201);}
 public function summary(Request $r,Patient $patient){abort_unless($r->user()->role==='admin'||$r->user()->id===$patient->user_id||in_array($r->user()->role,['doctor','specialist'])||($r->user()->role==='caregiver'&&\App\Models\CaregiverAccess::where('patient_id',$patient->id)->where('caregiver_id',$r->user()->id)->where('status','approved')->exists()),403);$obs=$patient->observations()->latest('recorded_at')->limit(10)->get();$last=$obs->first();return response()->json(['patient_id'=>$patient->id,'medical_history'=>$patient->medical_history,'allergies'=>$patient->allergies,'latest_observation'=>$last,'recent_observation_count'=>$obs->count(),'latest_assessments'=>$patient->assessments()->latest()->limit(5)->get(),'note'=>'Structured record summary; no generative medical interpretation.']);}
}
